    # Build row/col segments between dividers
    row_bounds = [-1] + divider_rows + [h]
    col_bounds = [-1] + divider_cols + [w]

    row_segs = []
    for i in range(len(row_bounds) - 1):
        a, b = row_bounds[i] + 1, row_bounds[i + 1]
        if a < b:
            row_segs.append((a, b))

    col_segs = []
    for i in range(len(col_bounds) - 1):
        a, b = col_bounds[i] + 1, col_bounds[i + 1]
        if a < b:
            col_segs.append((a, b))

    # Find a non-empty block template
    template = None
    template_size = None

    for rs, re in row_segs:
        for cs, ce in col_segs:
            block = [row[cs:ce] for row in grid[rs:re]]
            if any(val != 0 for row in block for val in row):
                template = block
                template_size = (re - rs, ce - cs)
                break
        if template is not None:
            break

    if template is None:
        return [row[:] for row in grid]

    # Copy grid and fill every same-sized segment block with the template
    out = [row[:] for row in grid]

    th, tw = template_size
    for rs, re in row_segs:
        for cs, ce in col_segs:
            if (re - rs, ce - cs) == (th, tw):
                for r in range(th):
                    for c in range(tw):
                        out[rs + r][cs + c] = template[r][c]

    return out

